import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import { useExpenses, useFunds } from "../../../api";
import { ExpenseTableRow, FundTableRow } from "../../../components";
import { useOutletContext } from "react-router-dom";
import { Dispatch, SetStateAction, useEffect } from "react";

export const ExpensesDetails = () => {
  const { searchText, dateFrom, dateTo, filterCategoryIds, setDisplayedCount } = useOutletContext<{
    searchText: string,
    dateFrom: Date,
    dateTo: Date,
    filterCategoryIds: number[],
    setDisplayedCount: Dispatch<SetStateAction<number>>
  }>();

  const { data: expenses } = useExpenses({
    searchText: searchText.trim(),
    dateFrom,
    dateTo,
    filterCategoryIds
  });
  const { data: funds } = useFunds({
    searchText: searchText.trim(),
    dateFrom,
    dateTo,
  });

  const combinedData = [...expenses ?? [], ...funds ?? []].sort((a, b) => b.date.getTime() - a.date.getTime());

  const tableRows = combinedData.filter(item => {
    return !('source' in item) || filterCategoryIds.includes(-1) || filterCategoryIds.includes(-2);
  }).map((item, index) => {
    if ('source' in item) {
      return <FundTableRow key={`fund-${item.id}`} index={index} fund={item} searchText={searchText} />;
    } else {
      return <ExpenseTableRow key={`expense-${item.id}`} index={index} expense={item} searchText={searchText} />;
    }
  });

  useEffect(() => {
    setDisplayedCount(tableRows.length);
  }, [tableRows.length]);

  return (
    <Box sx={{
      p: '32px',
      pt: 0,
      display: 'flex',
      overflowY: { xs: 'visible', sm: 'hidden' },
    }}>
      <TableContainer component={Paper}>
        <Table
          size="small"
          stickyHeader
          sx={{
            '& th': {
              backgroundColor: "primary.main",
              color: "primary.contrastText"
            }
          }}
        >
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold' }}>Date</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Category</TableCell>
              <TableCell sx={{ fontWeight: 'bold', textWrap: 'nowrap' }}>Description / Source</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Vendor</TableCell>
              <TableCell sx={{ fontWeight: 'bold' }}>Amount (CHF)</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {tableRows}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

