import {
	Box,
	Checkbox,
	FormControlLabel,
	IconButton,
	InputAdornment,
	TableCell,
	TableRow,
	TextField,
	Typography,
} from "@mui/material";
import { ExpenseType, Fund } from "../types";
import { Dispatch, SetStateAction, useContext, useEffect, useState } from "react";
import { Clear, Delete, Edit, Save } from "@mui/icons-material";
import dayjs from "dayjs";
import { DatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { useCreateFund, useDeleteFund, useEditFund } from "../api";
import { ConfirmDeleteDialog } from "./modals";
import { useCtrlS, UserContext } from "../utils";
import { SearchTextHighlight } from "./SearchTextHighlight";
import { useNavigate } from "react-router-dom";


export const FundTableRow = ({
	fund,
	index,
	editable = false, // Non-editable also means the component is used in the Details page, so it includes extra table cells
	searchText,
	isAddingFund,
	setIsAddingFund,
}: {
	fund: Fund;
	index: number;
	searchText: string;
	editable?: boolean;
	isAddingFund?: boolean;
	setIsAddingFund?: Dispatch<SetStateAction<boolean>>;
}) => {
	const navigate = useNavigate();
	const { userData } = useContext(UserContext);

	const [isEditing, setIsEditing] = useState(isAddingFund);
	const [date, setDate] = useState(dayjs(fund.date));
	const [source, setSource] = useState(fund.source);
	const [amount, setAmount] = useState(fund.amount);
	const [type, setType] = useState(fund.type);

	const { mutate: createFund, isPending: createLoading, isSuccess: createSuccess } = useCreateFund();
	const { mutate: editFund, isPending: editLoading, isSuccess: editSuccess } = useEditFund();
	const { mutate: deleteFund, isPending: deleteLoading } = useDeleteFund();

	const save = () => {
		if (!isEditing || !source.trim()) return;
		if (!isAddingFund)
			editFund({
				id: fund.id,
				date: date.toDate(),
				source: source.trim(),
				amount,
				type
			});
		else if (setIsAddingFund)
			createFund({
				date: date.toDate(),
				source: source.trim(),
				amount,
				type
			});
	};

	useCtrlS(save);

	useEffect(() => {
		if (createSuccess && setIsAddingFund) setIsAddingFund(false);
	}, [createSuccess]);

	useEffect(() => {
		if (editSuccess) setIsEditing(false);
	}, [editSuccess]);

	return (
		<TableRow
			sx={{
				backgroundColor: index % 2 === 0 ? "background.default" : "primary.light",
				":hover": editable ? { backgroundColor: "action.hover" } : {}
			}}
			onDoubleClick={editable ? () => setIsEditing(true) : undefined}
		>
			<TableCell>
				{!isEditing ? <Typography variant="body2"
					sx={editable || !userData?.showPrivateContent ? {} : { cursor: 'pointer', ":hover": { textDecoration: 'underline' } }}
					onClick={editable || !userData?.showPrivateContent ? undefined : () => {
						navigate("/diary", { state: { routedDate: date } });
					}}
				>
					{date.format("DD.MM.YYYY")}
				</Typography> :
					<LocalizationProvider dateAdapter={AdapterDayjs}>
						<DatePicker
							value={date}
							onChange={(newValue) => setDate(newValue ?? dayjs())}
							enableAccessibleFieldDOMStructure={false}
							format="DD.MM.YYYY"
							slotProps={{
								textField: {
									size: "small",
									variant: "standard",
									placeholder: "Date",
								}
							}}
							sx={{ minWidth: 130 }}
						/>
					</LocalizationProvider>
				}
			</TableCell>

			{!editable && (
				<TableCell>
					<Typography variant="body2">Funds</Typography>
				</TableCell>
			)}

			<TableCell width={"40%"}>
				{!isEditing ? <SearchTextHighlight text={source} searchText={searchText.trim()} /> :
					<TextField
						variant="standard"
						placeholder="Source"
						value={source}
						onChange={(e) => setSource(e.target.value)}
						sx={{ width: "100%" }}
					/>
				}
			</TableCell>

			{!editable && <TableCell />}

			<TableCell>
				{!isEditing ?
					<Typography variant="body2" sx={{
						color: editable ? "text.primary" : (
							amount >= 0 ? "success.main" : "error.main"
						)
					}}>
						{!editable ?
							(amount >= 0 ? `+${Math.abs(amount).toFixed(2)}` : `-${Math.abs(amount).toFixed(2)}`) :
							amount.toFixed(2)
						}
						{type === ExpenseType.Cash && " (Cash)"}
					</Typography> :
					<Box sx={{ display: 'flex', flexDirection: 'row', gap: 1, alignItems: 'center', minWidth: 170 }}>
						<TextField
							variant="standard"
							placeholder="Amount"
							value={amount.toFixed(2)}
							onChange={(e) => {
								const newAmount = parseFloat(e.target.value);
								setAmount(isNaN(newAmount) ? amount : newAmount);
							}}
							slotProps={{
								input: {
									endAdornment: <InputAdornment position="end">CHF</InputAdornment>,
								}
							}}
						/>
						<FormControlLabel
							control={
								<Checkbox
									size="small"
									sx={{ p: 0, pr: 0.5 }}
									checked={type === ExpenseType.Cash}
									onChange={(e) => setType(e.target.checked ? ExpenseType.Cash : ExpenseType.Bank_Manual)}
								/>
							}
							label={<Typography variant="body2">Cash</Typography>}
							sx={{ m: 0, ml: 1 }}
						/>
					</Box>
				}
			</TableCell>

			{editable && (
				!isEditing ? (
					<TableCell>
						<IconButton size="small"
							onClick={() => setIsEditing(true)}
						>
							<Edit fontSize="small" />
						</IconButton>
					</TableCell>
				) : (
					<TableCell sx={{ display: 'flex', gap: 1 }}>
						<IconButton
							size="small"
							color="success"
							loading={createLoading || editLoading}
							disabled={!source.trim()}
							onClick={save}>
							<Save fontSize="small" />
						</IconButton>

						{!isAddingFund && (
							<ConfirmDeleteDialog
								itemName={`fund: ${fund.source}`}
								deleteFn={() => deleteFund({ id: fund.id })} >
								<IconButton
									size="small"
									color="error"
									loading={deleteLoading}
								>
									<Delete fontSize="small" />
								</IconButton>
							</ConfirmDeleteDialog>
						)}

						<IconButton size="small" onClick={() => {
							if (!isAddingFund) {
								setDate(dayjs(fund.date));
								setSource(fund.source);
								setAmount(fund.amount);
								setIsEditing(false)
							} else if (setIsAddingFund) {
								setIsAddingFund(false);
							}
						}}>
							<Clear fontSize="small" />
						</IconButton>
					</TableCell>
				)
			)}
		</TableRow>
	)
}
