import {
  Box,
  Grid,
  IconButton,
  InputAdornment,
  MenuItem,
  Select,
  TextField,
  Typography
} from "@mui/material";
import styled from "styled-components";
import { VideoGame, VideoGameType } from "../types";
import {
  Edit,
  Today,
  Save,
  Delete,
  Clear,
  Check,
  CreditCard,
  SellOutlined,
  SportsEsportsOutlined,
  PeopleOutlineOutlined,
  InsertLink,
  AddPhotoAlternate,
  DoneAll
} from "@mui/icons-material";
import { Dispatch, SetStateAction, useEffect, useState } from "react";
import dayjs from "dayjs";
import { DatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { useCreateVideoGame, useDeleteVideoGame, useEditVideoGame } from "../api";
import { ConfirmDeleteDialog } from "./modals";
import { useCtrlS } from "../utils";
import { SearchTextHighlight } from "./SearchTextHighlight";

const videoGameTypeOptions = {
  [VideoGameType.Single_Player]: "Single Player",
  [VideoGameType.Online]: "Online",
  [VideoGameType.Both]: "Online & Single Player"
}

export const VideoGameCard = ({
  game,
  searchText,
  isAddingGame,
  setIsAddingGame
}: {
  game: VideoGame,
  searchText: string,
  isAddingGame?: boolean,
  setIsAddingGame?: Dispatch<SetStateAction<boolean>>
}) => {

  const [isEditing, setIsEditing] = useState(isAddingGame);
  const [name, setName] = useState(game.name);
  const [platform, setPlatform] = useState(game.platform);
  const [type, setType] = useState(game.type);
  const [completionCount, setCompletionCount] = useState(game.completionCount);
  const [firstPlayed, setFirstPlayed] = useState(dayjs(game.firstPlayed));
  const [price, setPrice] = useState(game.price);
  const [extraPurchases, setExtraPurchases] = useState(game.extraPurchases);
  const [storeUrl, setStoreUrl] = useState(game.storeUrl);
  const [coverImage, setCoverImage] = useState(game.coverImage);

  const { mutate: createGame, isPending: createLoading, isSuccess: createSuccess } = useCreateVideoGame();
  const { mutate: editGame, isPending: editLoading, isSuccess: editSuccess } = useEditVideoGame();
  const { mutate: deleteGame, isPending: deleteLoading } = useDeleteVideoGame();

  const save = () => {
    if (!isEditing || !name.trim()) return;
    if (!isAddingGame)
      editGame({
        id: game.id,
        name: name.trim(),
        platform: platform.trim(),
        type,
        completionCount,
        firstPlayed: firstPlayed.toDate(),
        price,
        extraPurchases,
        storeUrl: storeUrl.trim(),
        coverImage: coverImage?.trim()
      });
    else
      createGame({
        name: name.trim(),
        platform: platform.trim(),
        type,
        completionCount,
        firstPlayed: firstPlayed.toDate(),
        price,
        extraPurchases,
        storeUrl: storeUrl.trim(),
        coverImage: coverImage?.trim()
      });
  };

  useCtrlS(save);

  useEffect(() => {
    if (createSuccess && setIsAddingGame) setIsAddingGame(false);
  }, [createSuccess]);

  useEffect(() => {
    if (editSuccess) setIsEditing(false);
  }, [editSuccess]);

  return (
    <Wrapper
      sx={{ backgroundColor: 'primary.light' }}
      onDoubleClick={() => setIsEditing(true)}
    >
      <Box sx={{ width: '100%', aspectRatio: '16/9', position: 'relative' }} >
        {coverImage && (
          <CoverImage src={coverImage} />
        )}
        {isEditing && (
          <CoverImageEditor>
            <Box sx={{ borderRadius: '100px', backgroundColor: 'primary.light' }}>
              <IconButton>
                <AddPhotoAlternate />
              </IconButton>
            </Box>
          </CoverImageEditor>
        )}
      </Box>

      <ContentBox sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          {!isEditing ? (
            <Typography variant="h6" color="text.primary" sx={{ mr: 1 }}>
              <SearchTextHighlight text={name} searchText={searchText.trim()} />
            </Typography>
          ) : (
            <TextField
              variant="standard"
              placeholder="Name"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          )}

          {!isEditing && (
            <IconButton sx={{ ml: 'auto' }} onClick={() => setIsEditing(true)}>
              <Edit fontSize="small" />
            </IconButton>
          )}

          {isEditing && (
            <IconButton
              color="success"
              sx={{ ml: 'auto' }}
              loading={createLoading || editLoading}
              disabled={!name.trim()}
              onClick={save}
            >
              <Save fontSize="small" />
            </IconButton>
          )}

          {isEditing && !isAddingGame && (
            <ConfirmDeleteDialog
              itemName={`video game: ${name}`}
              deleteFn={() => deleteGame({ id: game.id })}
            >
              <IconButton
                color="error"
                loading={deleteLoading}
              >
                <Delete fontSize="small" />
              </IconButton>
            </ConfirmDeleteDialog>
          )}

          {isEditing && (
            <IconButton onClick={() => {
              if (!isAddingGame) {
                setName(game.name);
                setPlatform(game.platform);
                setType(game.type);
                setCompletionCount(game.completionCount);
                setFirstPlayed(dayjs(game.firstPlayed));
                setPrice(game.price);
                setExtraPurchases(game.extraPurchases);
                setStoreUrl(game.storeUrl);
                setCoverImage(game.coverImage);
                setIsEditing(false);
              } else if (setIsAddingGame) {
                setIsAddingGame(false);
              }
            }}>
              <Clear fontSize="small" />
            </IconButton>
          )}

          {!isEditing && storeUrl.trim() && (
            <IconButton onClick={() => window.open(storeUrl, '_blank')}>
              <InsertLink fontSize="small" />
            </IconButton>
          )}
        </Box>

        <Grid container rowSpacing={1} columnSpacing={2}>
          <Grid size={{ xs: 6 }} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <SportsEsportsOutlined sx={{ color: "text.primary" }} />
            {!isEditing ? (
              <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
                <SearchTextHighlight text={platform} searchText={searchText.trim()} />
              </Typography>
            ) : (
              <TextField
                variant="standard"
                placeholder="Platform"
                multiline
                value={platform}
                onChange={(e) => setPlatform(e.target.value)}
              />
            )}
          </Grid>

          <Grid size={{ xs: 6 }} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <PeopleOutlineOutlined sx={{ color: "text.primary" }} />
            {!isEditing ? (
              <Typography variant="body1">
                {videoGameTypeOptions[type]}
              </Typography>
            ) : (
              <Select
                variant="standard"
                sx={{ width: '100%', overflow: 'hidden' }}
                value={type}
                onChange={(e) => setType(e.target.value as VideoGameType)}
              >
                <MenuItem value={VideoGameType.Online}>{videoGameTypeOptions[VideoGameType.Online]}</MenuItem>
                <MenuItem value={VideoGameType.Single_Player}>{videoGameTypeOptions[VideoGameType.Single_Player]}</MenuItem>
                <MenuItem value={VideoGameType.Both}>{videoGameTypeOptions[VideoGameType.Both]}</MenuItem>
              </Select>
            )}
          </Grid>

          <Grid size={{ xs: 6 }} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {(firstPlayed.isAfter(dayjs('2000-01-01')) || isEditing) && <Today sx={{ color: "text.primary" }} />}
            {!isEditing ? (
              (firstPlayed.isAfter(dayjs('2000-01-01')) &&
                <Typography variant="body1">
                  {firstPlayed.format("DD.MM.YYYY")}
                </Typography>
              )
            ) : (
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DatePicker
                  value={firstPlayed}
                  onChange={(newValue) => setFirstPlayed(newValue ?? dayjs())}
                  enableAccessibleFieldDOMStructure={false}
                  format="DD.MM.YYYY"
                  slotProps={{
                    textField: {
                      size: "small",
                      variant: "standard",
                      placeholder: "First Played",
                    }
                  }}
                />
              </LocalizationProvider>
            )}
          </Grid>

          <Grid size={{ xs: 6 }} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {type !== VideoGameType.Online && (
              completionCount > 1 ? <DoneAll sx={{ color: "text.primary" }} /> :
                completionCount === 1 ? <Check sx={{ color: "text.primary" }} /> :
                  <Clear sx={{ color: "text.primary" }} />
            )}
            {type !== VideoGameType.Online && (
              !isEditing ? (
                <Typography variant="body1">
                  {completionCount}
                </Typography>
              ) : (
                <TextField
                  variant="standard"
                  placeholder="Completion Count"
                  value={completionCount}
                  onChange={(e) => {
                    const newCount = e.target.value === "" ? 0 : parseInt(e.target.value);
                    setCompletionCount(isNaN(newCount) ? completionCount : newCount);
                  }}
                />
              ))}
          </Grid>

          <Grid size={{ xs: (extraPurchases.trim() || isEditing) ? 6 : 12 }} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <SellOutlined sx={{ color: "text.primary" }} />
            {!isEditing ? (
              <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
                <SearchTextHighlight text={price} searchText={searchText.trim()} />
              </Typography>
            ) : (
              <TextField
                variant="standard"
                placeholder="Price"
                multiline
                value={price}
                onChange={(e) => setPrice(e.target.value)}
              />
            )}
          </Grid>

          <Grid size={{ xs: 6 }}
            sx={{
              display: (extraPurchases.trim() || isEditing) ? 'flex' : 'none',
              alignItems: 'center',
              gap: 1
            }}
          >
            <CreditCard sx={{ color: "text.primary" }} />
            {!isEditing ? (
              <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
                <SearchTextHighlight text={extraPurchases} searchText={searchText.trim()} />
              </Typography>
            ) : (
              <TextField
                variant="standard"
                placeholder="Extra Purchases"
                multiline
                value={extraPurchases}
                onChange={(e) => setExtraPurchases(e.target.value)}
              />
            )}
          </Grid>

          {isEditing && (
            <Grid size={{ xs: 12 }} sx={{ display: 'flex' }}>
              <TextField
                variant="standard"
                placeholder="Store URL"
                value={storeUrl}
                sx={{ flexGrow: 1 }}
                onChange={(e) => setStoreUrl(e.target.value)}
                slotProps={{
                  input: {
                    startAdornment: <InputAdornment position="start"><InsertLink /></InputAdornment>,
                  }
                }}
              />
            </Grid>
          )}

          {isEditing && (
            <Grid size={{ xs: 12 }} sx={{ display: 'flex' }}>
              <TextField
                variant="standard"
                placeholder="Cover Image URL"
                value={coverImage}
                sx={{ flexGrow: 1 }}
                onChange={(e) => setCoverImage(e.target.value)}
                slotProps={{
                  input: {
                    startAdornment: <InputAdornment position="start"><AddPhotoAlternate /></InputAdornment>,
                  }
                }}
              />
            </Grid>
          )}
        </Grid>
      </ContentBox>
    </Wrapper>
  )
}

const Wrapper = styled(Box)`
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  border-radius: 8px;
  border: ${({ theme }) => `solid 1px ${theme.palette.grey[700]}}`};
`;

const CoverImage = styled.img`
  border-top-left-radius: 8px;
  border-top-right-radius: 8px;
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
`;

const CoverImageEditor = styled(Box)`
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: #00000077;
  margin-bottom: 4px;
  display: flex;
  justify-content: center;
  align-items: center;
`;

const ContentBox = styled(Box)`
  padding: 24px;
  padding-top: 16px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
`;