import {
  Box,
  Checkbox,
  FormControlLabel,
  IconButton,
  InputAdornment,
  MenuItem,
  Select,
  TableCell,
  TableRow,
  TextField,
  Typography,
} from "@mui/material";
import { Expense, ExpenseType } from "../types";
import { Clear, Delete, Edit, Save } from "@mui/icons-material";
import { Dispatch, SetStateAction, useContext, useEffect, useState } from "react";
import { useCreateExpense, useDeleteExpense, useEditExpense, useExpensesCategories } from "../api";
import dayjs from "dayjs";
import { DatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { ConfirmDeleteDialog } from "./modals";
import { useCtrlS, UserContext } from "../utils";
import { SearchTextHighlight } from "./SearchTextHighlight";
import { useNavigate } from "react-router-dom";


export const ExpenseTableRow = ({
  expense,
  index,
  searchText,
  editable = false,
  isAddingExpense,
  setIsAddingExpense,
}: {
  expense: Expense;
  index: number;
  searchText: string;
  editable?: boolean;
  isAddingExpense?: boolean;
  setIsAddingExpense?: Dispatch<SetStateAction<boolean>>;
}) => {
  const navigate = useNavigate();
  const { userData } = useContext(UserContext);

  const [isEditing, setIsEditing] = useState(isAddingExpense);
  const [date, setDate] = useState(dayjs(expense.date));
  const [category, setCategory] = useState(expense.category);
  const [description, setDescription] = useState(expense.description);
  const [vendor, setVendor] = useState(expense.vendor);
  const [amount, setAmount] = useState(expense.amount);
  const [type, setType] = useState(expense.type);

  const { data: expensesCategories } = useExpensesCategories();

  const { mutate: createExpense, isPending: createLoading, isSuccess: createSuccess } = useCreateExpense();
  const { mutate: editExpense, isPending: editLoading, isSuccess: editSuccess } = useEditExpense();
  const { mutate: deleteExpense, isPending: deleteLoading } = useDeleteExpense();

  const save = () => {
    if (!isEditing || !description.trim()) return;
    if (!isAddingExpense)
      editExpense({
        id: expense.id,
        date: date.toDate(),
        categoryId: category?.id,
        description: description.trim(),
        vendor: vendor.trim(),
        amount,
        type
      });
    else if (setIsAddingExpense)
      createExpense({
        date: date.toDate(),
        categoryId: category?.id,
        description: description.trim(),
        vendor: vendor.trim(),
        amount,
        tags: [],
        type
      });
  };

  useCtrlS(save);

  // Handle case where category is deleted or renamed to update the displayed state
  useEffect(() => {
    setCategory(expense.category);
  }, [expense.category?.id, expense.category?.name]);

  useEffect(() => {
    if (createSuccess && setIsAddingExpense) setIsAddingExpense(false);
  }, [createSuccess]);

  useEffect(() => {
    if (editSuccess) setIsEditing(false);
  }, [editSuccess]);

  return (
    <TableRow
      sx={{
        backgroundColor: index % 2 === 0 ? "background.default" : "primary.light",
        ":hover": editable ? { backgroundColor: "action.hover" } : {}
      }}
      onDoubleClick={editable ? () => setIsEditing(true) : undefined}
    >
      <TableCell>
        {!isEditing ? <Typography variant="body2"
          sx={editable || !userData?.showPrivateContent ? {} : { cursor: 'pointer', ":hover": { textDecoration: 'underline' } }}
          onClick={editable || !userData?.showPrivateContent ? undefined : () => {
            navigate("/diary", { state: { routedDate: date } });
          }}
        >
          {date.format("DD.MM.YYYY")}
        </Typography> :
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DatePicker
              value={date}
              onChange={(newValue) => setDate(newValue ?? dayjs())}
              enableAccessibleFieldDOMStructure={false}
              format="DD.MM.YYYY"
              slotProps={{
                textField: {
                  size: "small",
                  variant: "standard",
                  placeholder: "Date",
                }
              }}
              sx={{ minWidth: 130 }}
            />
          </LocalizationProvider>
        }
      </TableCell>

      <TableCell>
        {!isEditing ? (
          category?.name ? (
            <Typography variant="body2" sx={{ whiteSpace: 'nowrap', color: category.color }}>
              <SearchTextHighlight text={category.name} searchText={searchText.trim()} />
            </Typography>
          ) : (
            <Typography color="gray" variant="body2">
              <em>Uncategorized</em>
            </Typography>
          )
        ) :
          <Select
            variant="standard"
            value={category?.id ?? "uncategorized"}
            sx={{ width: "100%" }}
            onChange={(e) => setCategory(expensesCategories?.find(cat => cat.id === e.target.value) ?? category)}
          >
            {!category && (
              <MenuItem value="uncategorized" disabled>
                <em>Uncategorized</em>
              </MenuItem>
            )}
            {expensesCategories?.map((cat) => (
              <MenuItem key={cat.id} value={cat.id}>
                {cat.name}
              </MenuItem>
            ))}
          </Select>
        }
      </TableCell>

      <TableCell width={"35%"}>
        {!isEditing ?
          <SearchTextHighlight text={description} searchText={searchText.trim()} />
          :
          <TextField
            variant="standard"
            placeholder="Description"
            value={description}
            sx={{ width: "100%" }}
            onChange={(e) => setDescription(e.target.value)}
          />
        }
      </TableCell>

      <TableCell>
        {!isEditing ?
          <SearchTextHighlight text={vendor} searchText={searchText.trim()} />
          :
          <TextField
            variant="standard"
            placeholder="Vendor"
            value={vendor}
            onChange={(e) => setVendor(e.target.value)}
          />
        }
      </TableCell>

      <TableCell>
        {!isEditing ?
          <Typography variant="body2">
            {!editable ?
              (amount >= 0 ? `-${Math.abs(amount).toFixed(2)}` : `+${Math.abs(amount).toFixed(2)}`) :
              amount.toFixed(2)}
            {type === ExpenseType.Cash && " (Cash)"}
          </Typography>
          :
          <Box sx={{ display: 'flex', flexDirection: 'row', gap: 1, alignItems: 'center', minWidth: 170 }}>
            <TextField
              variant="standard"
              placeholder="Amount"
              value={amount.toFixed(2)}
              onChange={(e) => {
                const newAmount = parseFloat(e.target.value);
                setAmount(isNaN(newAmount) ? amount : newAmount);
              }}
              slotProps={{
                input: {
                  endAdornment: <InputAdornment position="end">CHF</InputAdornment>,
                }
              }}
            />
            <FormControlLabel
              control={
                <Checkbox
                  size="small"
                  sx={{ p: 0, pr: 0.5 }}
                  checked={type === ExpenseType.Cash}
                  onChange={(e) => setType(e.target.checked ? ExpenseType.Cash : ExpenseType.Bank_Manual)}
                />
              }
              label={<Typography variant="body2">Cash</Typography>}
              sx={{ m: 0, ml: 1 }}
            />
          </Box>
        }
      </TableCell>

      {editable && (
        !isEditing ? (
          <TableCell>
            <IconButton
              size="small"
              onClick={() => setIsEditing(true)}
            >
              <Edit fontSize="small" />
            </IconButton>
          </TableCell>
        ) : (
          <TableCell sx={{ display: 'flex', gap: 1 }}>
            <IconButton
              size="small"
              color="success"
              loading={createLoading || editLoading}
              disabled={!description.trim()}
              onClick={save}>
              <Save fontSize="small" />
            </IconButton>

            {!isAddingExpense && (

              <ConfirmDeleteDialog
                itemName={`expense: ${description}`}
                deleteFn={() => deleteExpense({ id: expense.id })}
              >
                <IconButton
                  size="small"
                  color="error"
                  loading={deleteLoading}
                >
                  <Delete fontSize="small" />
                </IconButton>
              </ConfirmDeleteDialog>
            )}

            <IconButton size="small" onClick={() => {
              if (!isAddingExpense) {
                setDate(dayjs(expense.date));
                setCategory(expense.category);
                setDescription(expense.description);
                setVendor(expense.vendor);
                setAmount(expense.amount);
                setIsEditing(false);
              } else if (setIsAddingExpense) {
                setIsAddingExpense(false);
              }
            }}>
              <Clear fontSize="small" />
            </IconButton>
          </TableCell>
        )
      )}
    </TableRow>
  )
}
