import ReactDOM from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Theme, ThemeContext, ThemeData, UserContext, UserData } from "./utils";
import { useState } from "react";
import { Navigator } from "./navigation";
import client from "./api/client";
import { HttpStatusCode } from "axios";

const queryClient = new QueryClient();

const App = () => {
  const [userData, setUserData] = useState<UserData>();
  const [themeData, setThemeData] = useState<ThemeData>({ darkMode: userData?.darkMode ?? false });

  const contextData = {
    userData,
    setUserData: (userData?: UserData) => {
      if (!userData) {
        localStorage.removeItem("userData");
        setThemeData({ darkMode: false });
      }
      else {
        client.defaults.headers.common[
          "Authorization"
        ] = `Bearer ${userData?.token}`;
        setThemeData({ darkMode: userData.darkMode ?? true });

        client.interceptors.response.use(
          (res) => res,
          (err) => {
            if (err?.response?.status === HttpStatusCode.Unauthorized) {
              localStorage.removeItem("userData");
              setThemeData({ darkMode: false });
              setUserData(null);
            } else throw err;
          }
        );
      }
      localStorage.setItem("userData", JSON.stringify(userData));
      setUserData(userData);
    },
  };

  return (
    <UserContext.Provider value={contextData}>
      <ThemeContext.Provider value={{ themeData, setThemeData }}>
        <QueryClientProvider client={queryClient}>
          <Theme themeData={themeData}>
            <Navigator />
          </Theme>
        </QueryClientProvider>
      </ThemeContext.Provider>
    </UserContext.Provider>
  );
};

const root = ReactDOM.createRoot(document.getElementById("root") as HTMLElement);
root.render(<App />);
