import {
  Box,
  FormControl,
  FormControlLabel,
  Grid,
  Paper,
  Radio,
  RadioGroup,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  useTheme,
} from "@mui/material";
import styled from "styled-components";
import { useContext, useState } from "react";
import { useCurrentUser, useExpensesCategories, useExpensesStatistics, useMonthlyExpenses } from "../../../api";
import {
  Chart as ChartJS, ArcElement, Tooltip, Legend,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
} from 'chart.js';
import { Doughnut, Line } from 'react-chartjs-2';
import { ThemeContext } from "../../../utils";
import { ExpensesStatisticsCard } from "../../../components";
import dayjs from "dayjs";
import { useNavigate } from "react-router-dom";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

export const ExpensesStatistics = () => {
  const { palette } = useTheme();
  const { themeData } = useContext(ThemeContext);

  const navigate = useNavigate();

  const [overTimeType, setOverTimeType] = useState("both");

  const { data: user } = useCurrentUser();
  const { data: expensesCategories } = useExpensesCategories();
  const { data: statistics } = useExpensesStatistics();
  const { data: monthlyExpenses } = useMonthlyExpenses();

  if (!statistics || !user) return <div />
  return (
    <Wrapper sx={{ overflowY: { sx: 'unset', sm: 'auto' } }}>
      <Grid container spacing={2} flexGrow={1}>

        <Grid size={{ xs: 12, md: 6, lg: 4 }}>
          <ExpensesStatisticsCard
            title="Total Balance"
            value={statistics.totalBankFunds - statistics.totalBankExpenses + user.wallet}
            color="success.dark"
          />
        </Grid>

        <Grid size={{ xs: 12, md: 6, lg: 4 }}>
          <ExpensesStatisticsCard
            title="Bank Balance"
            value={statistics.totalBankFunds - statistics.totalBankExpenses}
            color="success.dark"
          />
        </Grid>

        <Grid size={{ xs: 12, md: 6, lg: 4 }} sx={{ display: 'flex' }}>
          <ExpensesStatisticsCard
            title="Wallet Balance"
            value={user.wallet}
            color="success.dark"
            isWallet
          />
        </Grid>

        <Grid size={{ xs: 12, md: 6 }}>
          <ExpensesStatisticsCard
            title="Total Spent This Month"
            value={statistics.totalExpensesThisMonth}
            color="primary.dark"
          />
        </Grid>

        <Grid size={{ xs: 12, md: 6 }}>
          <ExpensesStatisticsCard
            title="Average Expenses Per Month"
            value={statistics.monthlyAverageExpenses}
            color="warning.dark"
          />
        </Grid>
      </Grid>

      <Box sx={{ mt: 5, mb: { xs: 0, md: 5 } }}>
        <Grid container spacing={{ xs: 10, md: 5 }}>
          <Grid size={{ xs: 12, md: 6 }}>
            <Box sx={{
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: 1,
              maxHeight: '50vh',
            }}>
              <Typography variant="h5">
                Expenses Over Time
              </Typography>

              <FormControl>
                <RadioGroup row value={overTimeType} onChange={(e) => setOverTimeType(e.target.value)}>
                  <FormControlLabel value="expenses" control={<Radio />} label="Expenses" />
                  <FormControlLabel value="funds" control={<Radio />} label="Funds" />
                  <FormControlLabel value="both" control={<Radio />} label="Both" />
                </RadioGroup>
              </FormControl>

              <Line
                data={{
                  labels: Object.keys(statistics.months).sort(),
                  datasets: [
                    {
                      label: 'Amount (CHF)',
                      data: Object.entries(statistics.months)
                        .sort((a, b) => a[0].localeCompare(b[0]))
                        .map((m) => (
                          overTimeType === "expenses" ? m[1].expenses :
                            overTimeType === "funds" ? m[1].funds :
                              m[1].total
                        )),
                      backgroundColor:
                        overTimeType === "expenses" ? palette.warning.main :
                          overTimeType === "funds" ? palette.success.main :
                            palette.primary.main,
                      borderColor:
                        overTimeType === "expenses" ? palette.warning.main :
                          overTimeType === "funds" ? palette.success.main :
                            palette.primary.main,
                    }
                  ],
                }}
                options={{
                  scales: {
                    y: {
                      ticks: {
                        callback: (value) => `${value} CHF`,
                        color: themeData.darkMode ? palette.grey[400] : palette.grey[700],
                      }
                    },
                    x: {
                      ticks: {
                        color: themeData.darkMode ? palette.grey[400] : palette.grey[700],
                      }
                    }
                  },
                  plugins: {
                    legend: {
                      display: false
                    },
                  }
                }} />
            </Box>
          </Grid>

          <Grid size={{ xs: 12, md: 6 }}>
            <Box sx={{
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: 2,
              maxHeight: '50vh',
            }}>
              <Typography variant="h5">
                Monthly Expenses Per Category
              </Typography>

              <Doughnut
                data={{
                  labels: Object.keys(statistics.categories),
                  datasets: [
                    {
                      label: 'Amount (CHF)',
                      data: Object.values(statistics.categories).map(c => c.monthlyAverage),
                      backgroundColor: Object.keys(statistics.categories).map(c => expensesCategories?.find(cat => cat.name === c)?.color),
                    }
                  ],
                }}
                options={{
                  plugins: {
                    legend: {
                      position: "right",
                      align: "start",
                      labels:
                      {
                        color: themeData.darkMode ? palette.grey[400] : palette.grey[700],
                        font:
                        {
                          family: "Poppins, Inter, Segoe UI, sans-serif",
                          size: 18
                        }
                      }
                    },
                  },
                }} />
            </Box>
          </Grid>
        </Grid>
      </Box>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>

        <Typography variant="h5">
          Category Totals
        </Typography>

        <TableContainer component={Paper} sx={{ maxWidth: 'calc(100vw - 64px - 16px)' }}>
          <Table
            size="medium"
            sx={{
              '& th': {
                backgroundColor: "primary.main",
                color: "primary.contrastText"
              }
            }}
          >
            <TableHead>
              <TableRow>
                <TableCell />
                {Object.keys(statistics.categories).map((categoryName) => (
                  <TableCell key={categoryName} sx={{ fontWeight: 'bold' }}>
                    {categoryName}
                  </TableCell>
                ))}
                <TableCell sx={{ fontWeight: 'bold' }}>Total</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              <TableRow>
                <TableCell sx={{ fontWeight: 'bold' }}>Per Month</TableCell>
                {Object.values(statistics.categories).map((category, index) => (
                  <TableCell key={index}>
                    {category.monthlyAverage.toFixed(2)} CHF
                  </TableCell>
                ))}
                <TableCell>{statistics.monthlyAverageExpenses.toFixed(2)} CHF</TableCell>
              </TableRow>

              <TableRow>
                <TableCell sx={{ fontWeight: 'bold' }}>Total</TableCell>
                {Object.values(statistics.categories).map((category, index) => (
                  <TableCell key={index}>
                    {category.total.toFixed(2)} CHF
                  </TableCell>
                ))}
                <TableCell>{Object.values(statistics.categories).reduce((sum, cat) => sum + cat.total, 0).toFixed(2)} CHF</TableCell>
              </TableRow>
            </TableBody>
          </Table>
        </TableContainer>

        <Typography variant="h5" sx={{ mt: 3 }}>
          Monthly Expenses
        </Typography>

        <TableContainer component={Paper} sx={{ maxWidth: 'calc(100vw - 64px - 16px)' }}>
          <Table
            size="small"
            stickyHeader
            sx={{
              '& th': {
                backgroundColor: "primary.main",
                color: "primary.contrastText"
              }
            }}
          >
            <TableHead>
              <TableRow sx={{ backgroundColor: "primary.light" }}>
                <TableCell sx={{ fontWeight: 'bold' }}>Month</TableCell>
                {expensesCategories?.map((category) => (
                  <TableCell sx={{ fontWeight: 'bold' }} key={category.id}>
                    {category.name}
                  </TableCell>
                ))}
                <TableCell sx={{ fontWeight: 'bold' }}>Total</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {monthlyExpenses && Object.keys(monthlyExpenses).sort().reverse().map((month, index) => (
                <TableRow
                  key={month}
                  sx={{
                    backgroundColor: index % 2 === 0 ? "background.default" : "primary.light",
                  }}
                >
                  <TableCell
                    sx={{ cursor: 'pointer', ":hover": { textDecoration: 'underline' } }}
                    onClick={() => navigate("/expenses/details", {
                      state: {
                        routedDateFrom: dayjs(month).startOf('month').startOf('day').toDate(),
                        routedDateTo: dayjs(month).endOf('month').endOf('day').toDate(),
                        routedFilterCategoryIds: [-1],
                      }
                    })}>
                    {dayjs(month).format("MMMM YYYY")}
                  </TableCell>
                  {expensesCategories?.map((category) => (
                    <TableCell
                      key={category.id}
                      sx={{ cursor: 'pointer', ":hover": { textDecoration: 'underline' } }}
                      onClick={() => navigate("/expenses/details", {
                        state: {
                          routedDateFrom: dayjs(month).startOf('month').startOf('day').toDate(),
                          routedDateTo: dayjs(month).endOf('month').endOf('day').toDate(),
                          routedFilterCategoryIds: [category.id],
                        }
                      })}
                    >
                      {monthlyExpenses[month][category.name]?.toFixed(2)} CHF
                    </TableCell>
                  ))}
                  <TableCell>
                    {monthlyExpenses[month].total.toFixed(2)} CHF
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>

    </Wrapper>
  );
};

const Wrapper = styled(Box)`
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 32px;
  padding-top: 0;
`;
